def admit(active, waiting, budget, slots):
    # Validate inputs: active and waiting are lists of positive integers.
    for item in active:
        if not isinstance(item, int) or item <= 0:
            raise ValueError("active reservations must be positive integers")
    for item in waiting:
        if not isinstance(item, int) or item <= 0:
            raise ValueError("waiting reservations must be positive integers")

    # Check if any waiting reservation exceeds total budget.
    for value in waiting:
        if value > budget:
            raise ValueError("waiting reservation exceeds total budget")

    admitted = []
    for value in waiting:
        # Check if can be admitted given budget and slots.
        current_total = sum(active) + sum(admitted)
        if current_total + value <= budget and len(active) + len(admitted) < slots:
            admitted.append(value)
        else:
            # Stop at first unadmitted.
            break

    remaining = waiting[len(admitted):]
    return admitted, remaining

def endpoint(base_url, path):
    base = base_url.rstrip('/')
    # If base ends with /v1, remove it so we don't add it again
    if base.endswith('/v1'):
        base = base[:-3]  # Remove '/v1'
    return base.rstrip('/') + '/v1/' + path.lstrip('/')

