def admit(active, waiting, budget, slots):
    admitted = []
    total_active = sum(active)

    if any(value > budget for value in waiting):
        raise ValueError

    for value in waiting:
        if total_active + sum(admitted) + value <= budget:
            admitted.append(value)
        else:
            break

    remaining = [v for v in waiting if v not in admitted]
    return admitted, remaining
